const body = $input.first().json.body || $input.first().json;
function clean(value) { return String(value || '').trim(); }
function sql(value) { return clean(value).replace(/'/g, "''"); }
const cliente = {
  identificacion: clean(body.identificacion),
  nombres: clean(body.nombres),
  apellidos: clean(body.apellidos),
  telefono: clean(body.telefono),
  email: clean(body.email).toLowerCase(),
  direccion: clean(body.direccion),
  mascota: clean(body.mascota),
  especie: clean(body.especie),
  raza: clean(body.raza),
  observaciones: clean(body.observaciones)
};
const faltantes = ['identificacion', 'nombres', 'apellidos', 'telefono', 'email', 'mascota', 'especie'].filter((campo) => !cliente[campo]);
if (faltantes.length) {
  throw new Error(`Faltan campos obligatorios: ${faltantes.join(', ')}`);
}
return [{ json: {
  ...cliente,
  sql_identificacion: sql(cliente.identificacion),
  sql_nombres: sql(cliente.nombres),
  sql_apellidos: sql(cliente.apellidos),
  sql_telefono: sql(cliente.telefono),
  sql_email: sql(cliente.email),
  sql_direccion: sql(cliente.direccion),
  sql_mascota: sql(cliente.mascota),
  sql_especie: sql(cliente.especie),
  sql_raza: sql(cliente.raza),
  sql_observaciones: sql(cliente.observaciones)
} }];

const body = $input.first().json.body || $input.first().json;
function clean(value) { return String(value || '').trim(); }
function sql(value) { return clean(value).replace(/'/g, "''"); }
const tipo = clean(body.tipo_caso || body.tipo || 'Consulta general');
const hora = clean(body.hora).slice(0, 5);
const prioridades = { 'Emergencia': 'Alta', 'Consulta general': 'Media', 'Vacunacion': 'Baja' };
const cita = {
  identificacion: clean(body.identificacion),
  mascota: clean(body.mascota),
  especie: clean(body.especie),
  tipo_caso: tipo,
  prioridad: prioridades[tipo] || 'Media',
  fecha: clean(body.fecha),
  hora,
  hora_formateada: body.hora_formateada || hora,
  observaciones: clean(body.observaciones || body.obs)
};
const faltantes = ['identificacion', 'mascota', 'especie', 'tipo_caso', 'fecha', 'hora'].filter((campo) => !cita[campo]);
if (faltantes.length) {
  throw new Error(`Faltan campos obligatorios: ${faltantes.join(', ')}`);
}
return [{ json: {
  ...cita,
  sql_identificacion: sql(cita.identificacion),
  sql_mascota: sql(cita.mascota),
  sql_especie: sql(cita.especie),
  sql_tipo_caso: sql(cita.tipo_caso),
  sql_fecha: sql(cita.fecha),
  sql_hora: sql(cita.hora),
  sql_observaciones: sql(cita.observaciones)
} }];
